-- SQL_2026-08-18e — sweep the RETIRED commercial terms out of every webdesign.uk
-- site_spec. Owner instruction 2026-08-18: "remove the £1200 and related copy
-- from everywhere", and "sweep the briefing aspect".
--
-- WHY THIS IS BIGGER THAN THE BRIEFING ASPECT. evidence_base was corrected twice
-- on 2026-08-17/18 and the live PAGES were rewritten, but NINE other specs were
-- never swept and every one of them is an authority a writer or planner reads.
-- Census (2026-08-18): 9 aspects, 36 offending strings. The worst were not the
-- obvious ones:
--   * strategy      — its ENTIRE defensible_moat and gap_opportunity were the
--                     "refund-until-acceptance guarantee", which no longer exists.
--                     The stated moat is now cost and speed (one-shot AI build).
--   * content_direction — writing_rules[10] INSTRUCTED writers to state "the number
--                     of revision rounds included in the price and the length of the
--                     review window". That is a live instruction to write retired,
--                     now-BANNED claims. A plausible source of the faq rewrite that
--                     failed 2026-08-18 11:47Z on banned claim "rounds of changes"
--                     (plausible, NOT traced — do not record it as the cause).
--   * briefing      — £1,200, "You only pay if you like it", the 14-day window,
--                     "two rounds of revisions". Read by build-site-planner.
--
-- TWO TRAPS PAID FOR IN WRITING THIS, both recorded in NOTES:
--   1. `submission` EMBEDS its own copies of mission_brief and roadmap_brief, with
--      text that DIFFERS from the standalone aspects. Fixing the standalone ones
--      leaves submission asserting the old terms.
--   2. `content_direction` carries BOTH structured fields AND a rendered `formatted`
--      string duplicating them. Fixing the structured fields left `formatted` stale
--      and authoritative-looking. Mirrored, but only on anchors >=25 chars: a blind
--      replace of the short key-terms ("refund", "acceptance") corrupted unrelated
--      sentences into "Never describe the no refunds or revision right".
--
-- WHAT IS DELIBERATELY LEFT: the words "revision round" and "review window" survive
-- SIX and TWO times, ALWAYS inside a DENIAL ("no approval stage and no revision
-- rounds"; "never describe a review window ... because none exist"). Removing the
-- vocabulary entirely would stop us telling the writer what NOT to invent. Each was
-- read in context. The seven phrases that must never be ASSERTED are asserted
-- nowhere, and the verify block below proves it.
--
-- Facts/keys: every top-level key set is unchanged in all 9 aspects (asserted in
-- Python before this file was generated, and again here).

BEGIN;

-- ── briefing ──
WITH cur AS (
  SELECT ss.id, ss.site_id, ss.pinned FROM site_specs ss JOIN sites s ON s.id=ss.site_id
   WHERE s.domain='webdesign.uk' AND ss.aspect='briefing' AND ss.is_current
),
retire AS (UPDATE site_specs ss SET is_current=false, superseded_at=now()
            WHERE ss.id=(SELECT id FROM cur) RETURNING 1)
INSERT INTO site_specs (site_id, aspect, data, source, notes, is_current, created_by, pinned)
SELECT c.site_id, 'briefing', '{"gaps": ["leadership_team: no named individuals or team members identified in research data", "case_studies: service is new with no delivered work or client history to draw on", "headquarters: only known to be UK, no specific city or address available"], "tone": "professional", "tagline": "A complete starter website, built in one pass, for £149.", "about_us": "webdesign.uk builds complete starter websites for a single fixed price of £149 with no VAT, no monthly fees to us, and no lock-in. It builds any sort of site, not just business sites. You tell us what you want and we build it once. You pay the £149 in full before any work starts, and you do not see the site before paying. It is usually ready the next day once we have what we need from you. What you get is a starter site with its initial copy written: a site you start with and edit, not a finished final product. You receive a ZIP of the finished site to keep, with instructions for putting it online, and your site already live at a link we host for about a month. No changes are included and we do not offer refunds. That is what the low fixed price pays for.", "has_blog": false, "industry": "Web Design & Development", "services": [{"name": "Complete website build", "description": "A complete starter website, built in one pass. One fixed price of £149, no VAT, no monthly fee to us, and no lock-in. Payment is taken in full before the build starts and there is no approval stage: the site is built once, and that is how the price stays down. Usually ready the next day from having what we need from you. Delivered as a ZIP of the files to keep plus the site live at a link we host for about a month. No changes are included and we do not offer refunds."}, {"name": "Domain rental or purchase", "description": "The site is delivered hosted by us under a domain the customer can rent at £10 a month, with the subscription link in the delivery email, or buy outright for a one-off £200 and then transfer freely to their own registrar or host. Keeping the site online beyond the included month otherwise means hosting it themselves, and free options are recommended by name."}], "site_type": "brochure", "has_careers": false, "case_studies": null, "company_name": "webdesign.uk", "headquarters": "United Kingdom", "contact_email": "webdesign@contactforsales.com", "contact_phone": "+44 (0) 7934 524 911", "leadership_team": null, "briefing_confidence": 0.82, "recommended_builder": "pageflow-builder"}'::jsonb, 'owner-instruction',
  'SQL_2026-08-18e: retired commercial terms swept (owner 2026-08-18). Top-level keys unchanged.',
  true, 'webdesign_uk_build_service lane', c.pinned
FROM cur c, retire;
-- ── content_direction ──
WITH cur AS (
  SELECT ss.id, ss.site_id, ss.pinned FROM site_specs ss JOIN sites s ON s.id=ss.site_id
   WHERE s.domain='webdesign.uk' AND ss.aspect='content_direction' AND ss.is_current
),
retire AS (UPDATE site_specs ss SET is_current=false, superseded_at=now()
            WHERE ss.id=(SELECT id FROM cur) RETURNING 1)
INSERT INTO site_specs (site_id, aspect, data, source, notes, is_current, created_by, pinned)
SELECT c.site_id, 'content_direction', '{"voice": {"person": "Second person singular (you / your) for the reader throughout. First person plural (we / us) for the studio, used sparingly and only when necessary.", "register": "Down-to-earth and matter-of-fact. Talks to a busy business owner the way a competent tradesperson would — here is what you get, here is what it costs, here is how it works. No sales register at all.", "formality": "Informal enough to use contractions and short sentences. Formal enough never to be jokey or chatty. Sits closest to a clear, well-written business letter — not a pitch deck, not a blog post.", "emotional_tone": "Calm and unruffled. The reader is sceptical and has been burnt before; the writing acknowledges this implicitly by refusing to oversell. The feeling is: competent people who are not trying to impress you.", "authority_level": "Authority is demonstrated by clarity and specificity, not by claimed credentials or client counts. The site does not assert expertise — it shows it by being well-made, well-written, and straightforward about every term."}, "cta_style": {"approach": "Low-pressure and specific. Tell the reader exactly what happens when they act. No ''get started today'', no countdown urgency. The CTA is an invitation to a conversation, not a close.", "verb_choices": "Get in touch. Send us an email. Call us. Ask a question. These are the register. Never: ''Claim your free consultation'', ''Book now'', ''Start your journey''."}, "formatted": "Voice:\nPerson: Second person singular (you / your) for the reader throughout. First person plural (we / us) for the studio, used sparingly and only when necessary.\nRegister: Down-to-earth and matter-of-fact. Talks to a busy business owner the way a competent tradesperson would — here is what you get, here is what it costs, here is how it works. No sales register at all.\nFormality: Informal enough to use contractions and short sentences. Formal enough never to be jokey or chatty. Sits closest to a clear, well-written business letter — not a pitch deck, not a blog post.\nEmotional tone: Calm and unruffled. The reader is sceptical and has been burnt before; the writing acknowledges this implicitly by refusing to oversell. The feeling is: competent people who are not trying to impress you.\nAuthority level: Authority is demonstrated by clarity and specificity, not by claimed credentials or client counts. The site does not assert expertise — it shows it by being well-made, well-written, and straightforward about every term.\n\nCta style:\nApproach: Low-pressure and specific. Tell the reader exactly what happens when they act. No ''get started today'', no countdown urgency. The CTA is an invitation to a conversation, not a close.\nVerb choices: Get in touch. Send us an email. Call us. Ask a question. These are the register. Never: ''Claim your free consultation'', ''Book now'', ''Start your journey''.\n\nTerminology:\nApproach: Use plain words wherever a plain word exists. Technical terms that the customer does not need to understand should be handled by the studio — the copy says so and moves on. Where a term must be used (domain, hosting, CMS), define it once in the plainest possible way.\nKey terms:\n- domain\n- hosting\n- live link\n- one-shot build\n- fixed price\n- going live\n- page copy\n- no refunds\n- scope\n\nContent depth:\nThoroughness: Thorough on the things a sceptic would ask, brief on everything else. Every page earns its length. If a sentence can be cut without loss, cut it.\nAssumed knowledge: The reader knows what a website is and roughly what they want. They do not know the difference between hosting providers, DNS records, or CMS platforms, and they do not need to — those are the studio''s problem, and the content should say so.\nExplanation pattern: State the fact or term plainly first. If it needs a brief explanation, give one immediately in the same sentence or the next. Never send the reader to a footnote or a link to understand something on the current page.\n\nHeading style:\nFormat: Plain declarative statements or direct questions — the kind a buyer would type into a search bar. No puns, no wordplay, no agency-flavoured mystery. H1s state the proposition. H2s name the section clearly. H3s (where used) answer a specific sub-question.\nHierarchy: H1 once per page, states the core proposition of that page. H2 for major sections. H3 only for FAQ-style questions or genuinely distinct sub-sections. Do not use heading levels for decoration or emphasis.\n\nWriting rules:\n- Never use the word ''bespoke'', ''solution'', ''digital experience'', ''journey'', ''passion'', ''transform'', ''leverage'', or ''deliver'' in the agency sense.\n- State the price as a specific number. Do not describe it as ''competitive'', ''affordable'', or ''great value'' — let it speak for itself.\n- Say what is not included as clearly as what is. Vagueness about scope is what burns buyers; transparency is the differentiator.\n- Never promise a specific outcome for the customer''s business — webdesign.uk builds the site; what the customer does with it is theirs.\n- Do not write in the future tense when the present tense works: ''You get a ZIP of the files'' not ''You will receive a ZIP of the files''.\n- Use ''you'' and ''we'' throughout but keep ''we'' statements rare — the page is about the reader''s situation, not the studio''s capabilities.\n- Every factual claim (price, timescale, what is and is not included) must match the evidence base or be flagged as not yet confirmed. Do not invent numbers.\n- Headings should complete a thought or state a fact, not tease one. ''What happens if you change your mind'' not ''The no-risk promise''.\n- The FAQ page answers the actual questions — no softening, no reframing, no burying the uncomfortable answer in the middle of a paragraph.\n- Avoid parenthetical asides and em-dash chains. If the thought is worth including, give it its own sentence.\n- Wherever a page discusses payment, changes or what happens after delivery, state the specific terms from the evidence base: payment in full before the build, no approval stage, no changes included, and no refunds. Never soften these into something open-ended, and never describe a review window, an approval step or a revision round, because none exist. State a denial in the plain form ''we do not offer refunds'' rather than ''there is no refund'', which the claims gate reads as a refund promise and will block the page.\n\nSentence style:\nRhythm: Flat and steady. No rhetorical build-up, no dramatic pauses, no lists of three designed to feel conclusive. The rhythm should feel like someone giving you a straight answer.\nAverage length: Short. Aim for ten to fourteen words on average. Never write a sentence that requires re-reading to parse.\nStructure patterns: Subject-verb-object. One idea per sentence. Lead with what matters most. Use full stops where lesser writers use commas. Lists only when the content is genuinely list-shaped, not to pad.\n\nExample phrases:\nCharacteristic:\n- You pay once. There is no monthly fee and nothing you are locked into.\n- You pay the £149 first, then we build it. We do not offer refunds.\n- We write the words as well as build the pages — you do not need to hand us finished copy.\n- No changes are included. The files are yours, and you or anyone you choose can edit them.\n- The site you are looking at now is the work. Judge it accordingly.\nWould never say:\n- We''re passionate about crafting bespoke digital experiences that transform your online presence.\n- Our proven process delivers results-driven websites tailored to your unique business goals.\n- Join hundreds of satisfied clients who trust us to elevate their brand.\n- Book your free strategy session today — limited availability!\n- We leverage cutting-edge technology to future-proof your digital journey.\n\nParagraph style:\nStructure: State the point, give one supporting fact or clarification if needed, stop. No wind-up sentences. No summary sentences that repeat what the paragraph just said.\nTypical length: Two to four sentences maximum. One idea per paragraph. Single-sentence paragraphs are fine when the statement stands alone.\n\nThings to avoid:\n- All agency marketing language: solutions, bespoke digital experiences, passionate about pixels, data-driven, full-service, end-to-end, holistic\n- Visual clichés of the web design trade: wireframe sketches, colour-swatch fans, browser windows drawn at an angle, laptop mockups floating on gradients\n- Invented social proof: testimonials, star ratings, client logos, years-of-experience counts, or project counts that do not exist yet\n- Urgency or scarcity language: ''limited availability'', ''act now'', ''only a few spots left''\n- Vague scope: phrases like ''as many revisions as you need'' or ''ongoing support included'' without defining precisely what is meant\n- Passive constructions that obscure who does what: ''your site will be built'' rather than ''we build your site''\n- Promises about business outcomes: ''grow your customer base'', ''increase conversions'', ''outrank your competitors''\n- Exclamation marks anywhere on the site\n\nThings to emulate:\n- The directness of a well-written price list — state what is included, state what it costs, state any conditions\n- The clarity of good legal drafting — every term defined, no ambiguity about who owns what or what happens in each scenario\n- The confidence of a studio that does not need to prove itself through volume of claims — fewer, truer statements\n- The FAQ approach of a company that has already thought of every hard question and is not afraid of any of them\n- The plain-language tradition of the best UK government service writing — GOV.UK as a tonal reference for clarity, not for context\n- Short navigational headings that tell the reader exactly where they are and what this page answers\n- Process descriptions that name each step concretely rather than abstractly: ''We send you a ZIP of the files and a link to your site already live'' not ''We share our work with you''\n\nPersuasion approach:\nMethod: Explanation is the persuasion. The offer is unusual enough that a clear, complete account of it does the selling. No urgency, no scarcity, no social proof manufactured for a new service. Specificity does what superlatives cannot.\nTrust building: State the limits plainly and early, in the same breath as the price: payment first, no sight of the site before paying, no approval stage, no changes, no refunds. The offer only works if the reader believes the terms are exactly what they say, so understating a limit costs more trust than it buys. Be specific about what is and is not included. Say plainly when the evidence base does not support a claim rather than inventing one. Honour the reader''s intelligence.\nSocial proof style: No testimonials, no client counts, no case studies — the service is new and the site must not pretend otherwise. The site itself is the social proof. Nothing is invented. If and when real work exists, it is shown as it is.", "terminology": {"approach": "Use plain words wherever a plain word exists. Technical terms that the customer does not need to understand should be handled by the studio — the copy says so and moves on. Where a term must be used (domain, hosting, CMS), define it once in the plainest possible way.", "key_terms": ["domain", "hosting", "live link", "one-shot build", "fixed price", "going live", "page copy", "no refunds", "scope"]}, "content_depth": {"thoroughness": "Thorough on the things a sceptic would ask, brief on everything else. Every page earns its length. If a sentence can be cut without loss, cut it.", "assumed_knowledge": "The reader knows what a website is and roughly what they want. They do not know the difference between hosting providers, DNS records, or CMS platforms, and they do not need to — those are the studio''s problem, and the content should say so.", "explanation_pattern": "State the fact or term plainly first. If it needs a brief explanation, give one immediately in the same sentence or the next. Never send the reader to a footnote or a link to understand something on the current page."}, "heading_style": {"format": "Plain declarative statements or direct questions — the kind a buyer would type into a search bar. No puns, no wordplay, no agency-flavoured mystery. H1s state the proposition. H2s name the section clearly. H3s (where used) answer a specific sub-question.", "hierarchy": "H1 once per page, states the core proposition of that page. H2 for major sections. H3 only for FAQ-style questions or genuinely distinct sub-sections. Do not use heading levels for decoration or emphasis."}, "writing_rules": ["Never use the word ''bespoke'', ''solution'', ''digital experience'', ''journey'', ''passion'', ''transform'', ''leverage'', or ''deliver'' in the agency sense.", "State the price as a specific number. Do not describe it as ''competitive'', ''affordable'', or ''great value'' — let it speak for itself.", "Say what is not included as clearly as what is. Vagueness about scope is what burns buyers; transparency is the differentiator.", "Never promise a specific outcome for the customer''s business — webdesign.uk builds the site; what the customer does with it is theirs.", "Do not write in the future tense when the present tense works: ''You get a ZIP of the files'' not ''You will receive a ZIP of the files''.", "Use ''you'' and ''we'' throughout but keep ''we'' statements rare — the page is about the reader''s situation, not the studio''s capabilities.", "Every factual claim (price, timescale, what is and is not included) must match the evidence base or be flagged as not yet confirmed. Do not invent numbers.", "Headings should complete a thought or state a fact, not tease one. ''What happens if you change your mind'' not ''The no-risk promise''.", "The FAQ page answers the actual questions — no softening, no reframing, no burying the uncomfortable answer in the middle of a paragraph.", "Avoid parenthetical asides and em-dash chains. If the thought is worth including, give it its own sentence.", "Wherever a page discusses payment, changes or what happens after delivery, state the specific terms from the evidence base: payment in full before the build, no approval stage, no changes included, and no refunds. Never soften these into something open-ended, and never describe a review window, an approval step or a revision round, because none exist. State a denial in the plain form ''we do not offer refunds'' rather than ''there is no refund'', which the claims gate reads as a refund promise and will block the page."], "sentence_style": {"rhythm": "Flat and steady. No rhetorical build-up, no dramatic pauses, no lists of three designed to feel conclusive. The rhythm should feel like someone giving you a straight answer.", "average_length": "Short. Aim for ten to fourteen words on average. Never write a sentence that requires re-reading to parse.", "structure_patterns": "Subject-verb-object. One idea per sentence. Lead with what matters most. Use full stops where lesser writers use commas. Lists only when the content is genuinely list-shaped, not to pad."}, "example_phrases": {"characteristic": ["You pay once. There is no monthly fee and nothing you are locked into.", "You pay the £149 first, then we build it. We do not offer refunds.", "We write the words as well as build the pages — you do not need to hand us finished copy.", "No changes are included. The files are yours, and you or anyone you choose can edit them.", "The site you are looking at now is the work. Judge it accordingly."], "would_never_say": ["We''re passionate about crafting bespoke digital experiences that transform your online presence.", "Our proven process delivers results-driven websites tailored to your unique business goals.", "Join hundreds of satisfied clients who trust us to elevate their brand.", "Book your free strategy session today — limited availability!", "We leverage cutting-edge technology to future-proof your digital journey."]}, "paragraph_style": {"structure": "State the point, give one supporting fact or clarification if needed, stop. No wind-up sentences. No summary sentences that repeat what the paragraph just said.", "typical_length": "Two to four sentences maximum. One idea per paragraph. Single-sentence paragraphs are fine when the statement stands alone."}, "things_to_avoid": ["All agency marketing language: solutions, bespoke digital experiences, passionate about pixels, data-driven, full-service, end-to-end, holistic", "Visual clichés of the web design trade: wireframe sketches, colour-swatch fans, browser windows drawn at an angle, laptop mockups floating on gradients", "Invented social proof: testimonials, star ratings, client logos, years-of-experience counts, or project counts that do not exist yet", "Urgency or scarcity language: ''limited availability'', ''act now'', ''only a few spots left''", "Vague scope: phrases like ''as many revisions as you need'' or ''ongoing support included'' without defining precisely what is meant", "Passive constructions that obscure who does what: ''your site will be built'' rather than ''we build your site''", "Promises about business outcomes: ''grow your customer base'', ''increase conversions'', ''outrank your competitors''", "Exclamation marks anywhere on the site"], "compliance_rules": [], "things_to_emulate": ["The directness of a well-written price list — state what is included, state what it costs, state any conditions", "The clarity of good legal drafting — every term defined, no ambiguity about who owns what or what happens in each scenario", "The confidence of a studio that does not need to prove itself through volume of claims — fewer, truer statements", "The FAQ approach of a company that has already thought of every hard question and is not afraid of any of them", "The plain-language tradition of the best UK government service writing — GOV.UK as a tonal reference for clarity, not for context", "Short navigational headings that tell the reader exactly where they are and what this page answers", "Process descriptions that name each step concretely rather than abstractly: ''We send you a ZIP of the files and a link to your site already live'' not ''We share our work with you''"], "persuasion_approach": {"method": "Explanation is the persuasion. The offer is unusual enough that a clear, complete account of it does the selling. No urgency, no scarcity, no social proof manufactured for a new service. Specificity does what superlatives cannot.", "trust_building": "State the limits plainly and early, in the same breath as the price: payment first, no sight of the site before paying, no approval stage, no changes, no refunds. The offer only works if the reader believes the terms are exactly what they say, so understating a limit costs more trust than it buys. Be specific about what is and is not included. Say plainly when the evidence base does not support a claim rather than inventing one. Honour the reader''s intelligence.", "social_proof_style": "No testimonials, no client counts, no case studies — the service is new and the site must not pretend otherwise. The site itself is the social proof. Nothing is invented. If and when real work exists, it is shown as it is."}}'::jsonb, 'owner-instruction',
