SELECT c.site_id, 'identity', '{"contact": {"email": null, "phone": null, "address": null, "location": "United Kingdom"}, "tagline": null, "industry": "Web Design & Development", "services": [{"name": "Complete website build", "description": "All pages the business actually needs, with copy written for that business, design, and deployment live on the customer''s own domain — one fixed price, paid once, no ongoing fee."}, {"name": "Post-acceptance changes", "description": "Changes requested after acceptance are scoped and charged as work. Anything that is the studio''s own mistake is put right at no cost."}], "key_people": [], "company_name": "webdesign.uk", "sub_industry": "Fixed-price one-shot starter websites for any sort of site, not businesses only", "about_summary": "webdesign.uk builds complete starter websites for a single fixed price with no ongoing fees, for anyone who wants one rather than businesses only. A customer says what they want and provides their domain; webdesign.uk handles the pages, copy, design and going live. Payment is taken in full before the build, there is no approval stage, and the site is built once. It is delivered as a ZIP of the files to keep plus the site live at a link hosted for about a month. No changes are included and no refunds are offered.", "social_profiles": {}, "target_audience": "Anyone in the UK who needs a website and does not want to build one: small and medium business owners, but equally people building a personal, community, club or project site. Typically not technical, often quoted far higher by an agency or sold a page-builder subscription they never finished, sceptical of marketing promises, and willing to trade revisions and hand-holding for a low fixed price and a fast turnaround.", "competitors_found": ["cheapwebdesign.co.uk", "dcpweb.co.uk", "the-web-design-company.co.uk", "bluefrontier.co.uk"], "has_existing_site": false, "existing_site_quality": "none", "unique_selling_points": ["One fixed price of £149, paid once, with no subscription, no monthly fee and no lock-in", "One-shot and fast: no approval stage and no revision rounds, usually ready the next day, which is how the price stays down", "Everything included: pages, copy written for the business, design, and going live on their own domain", "Plain language and honest terms — no agency jargon, no overselling", "Mistakes are put right at no cost; requested changes are charged transparently as work", "Customer retains full ownership of the site on acceptance"]}'::jsonb, 'owner-instruction',
  'SQL_2026-08-18e: retired commercial terms swept (owner 2026-08-18). Top-level keys unchanged.',
  true, 'webdesign_uk_build_service lane', c.pinned
FROM cur c, retire;
-- ── mission_brief ──
WITH cur AS (
  SELECT ss.id, ss.site_id, ss.pinned FROM site_specs ss JOIN sites s ON s.id=ss.site_id
   WHERE s.domain='webdesign.uk' AND ss.aspect='mission_brief' AND ss.is_current
),
retire AS (UPDATE site_specs ss SET is_current=false, superseded_at=now()
            WHERE ss.id=(SELECT id FROM cur) RETURNING 1)
INSERT INTO site_specs (site_id, aspect, data, source, notes, is_current, created_by, pinned)
SELECT c.site_id, 'mission_brief', '{"text": "webdesign.uk sells complete starter websites for one fixed price. It builds any sort of site, not just business sites: personal, community, club and project sites are all in scope. A customer comes to us with a domain and a description of what they want, and we build the whole site: the pages it needs, the words on them, the design, and getting it live. It is one fixed price paid once, with no ongoing fee to us and nothing the customer is locked into. Payment comes first: they pay in full before any work starts and do not see the site before paying. There is no approval stage and no revision rounds. The site is built once, and that is how the price stays down. What they get is a starter site with its initial copy written, which they are expected to edit, delivered as a ZIP of the files to keep plus the site already live at a link we host for about a month. No changes are included and we do not offer refunds. The people buying this need a decent website and have neither the time to make one nor the appetite for a drawn-out agency process. They are not technical. They have often been quoted far more than this by an agency, or have been sold a page builder subscription and never finished the site. They are sceptical, they have been oversold to before, and they respond to someone talking plainly about what they will actually get. The site should do three things. It should explain the offer clearly enough that someone understands it without asking. It should ask the visitor a little about themselves and what they are after, just a little, as an opening to a conversation rather than a form to be qualified by. And it should help them work out what to ask for, because the site is built in one pass from what they give us. The tone is plain, direct British English, written for someone who does not enjoy being sold to. Short sentences and ordinary words. This is a new service with no history to trade on, so it must not reach for the things a new service does not have. It should sound like a competent small studio that is confident about the work and relaxed about proving it, not like a startup announcing itself. Restraint reads as confidence here. Overselling would read as exactly the thing these buyers have been burnt by before. Avoid the whole register of agency marketing language: no talk of solutions, no bespoke digital experiences, no passion for pixels, no promises to transform anyone''s business. Avoid the visual cliches of the web design trade as well, the wireframe sketches and fanned colour swatches and browser windows drawn at an angle. The site is itself the portfolio piece, so what it demonstrates matters more than what it asserts."}'::jsonb, 'owner-instruction',
  'SQL_2026-08-18e: retired commercial terms swept (owner 2026-08-18). Top-level keys unchanged.',
  true, 'webdesign_uk_build_service lane', c.pinned
FROM cur c, retire;
-- ── roadmap_brief ──
WITH cur AS (
  SELECT ss.id, ss.site_id, ss.pinned FROM site_specs ss JOIN sites s ON s.id=ss.site_id
   WHERE s.domain='webdesign.uk' AND ss.aspect='roadmap_brief' AND ss.is_current
),
retire AS (UPDATE site_specs ss SET is_current=false, superseded_at=now()
            WHERE ss.id=(SELECT id FROM cur) RETURNING 1)
INSERT INTO site_specs (site_id, aspect, data, source, notes, is_current, created_by, pinned)
SELECT c.site_id, 'roadmap_brief', '{"text": "Phase one built five pages; this roadmap now also covers phase five, which adds exactly one new element: a chat box on the contact page, now that the chat service behind it exists (127.0.0.1:8081 on the box, reached through /api/chat). No page other than contact may include a chat box, an input box wired to a backend, or any other form. **index** — the home page. What webdesign.uk sells: a complete starter website, any sort of site and not just business sites, built and put live on the customer''s own domain, for one fixed price paid once before the build, with no ongoing fee and nothing the customer is locked into. Say what happens from first contact to going live in one short passage and point at how-it-works for the detail. State the price plainly, drawing it from the evidence base. No invented portfolio, no testimonials, no client counts, no years of experience — the site is new, and the page must not pretend otherwise; the site itself is the demonstration piece. **how-it-works** — the process from first email to live site, step by step, in plain words: what we need from the customer, that payment is taken in full before any work starts and they do not see the site before paying, that there is no approval stage and the site is built once, what they receive at the end (a ZIP of the files to keep, with instructions, plus the site already live at a link we host for about a month), that no changes are included and we do not offer refunds, and what keeping the site online after that month involves. **what-you-get** — exactly what is included: the pages the site actually needs, the words on them written for it, the design, and getting it live on their own domain; and what is not included, said as plainly as what is. **faq** — the questions a sceptical buyer actually asks, answered honestly and briefly: what it costs and whether VAT applies, how long it takes, who owns the site (they do, outright), why payment comes first, why there is no approval stage and no changes are included, why we do not offer refunds, what we need from them to start, and what happens with their domain and hosting, including renting it monthly or buying it outright. Every number and named commitment on this page comes from the evidence base; where the evidence base holds no answer, the page says so plainly rather than inventing one. **contact** — hero, then the chat box (pinned section_type ''chat-input-box'', component name chat-input-box, placed immediately after the hero — this is the ONLY page that gets it; do not place a backend-dependent section on any other page without first updating this site''s deploy_config.capabilities), then the plain fallback: email and phone, no response-time promises, no form beyond the chat box already above. The ''what to put in a first message'' guidance is now the chat''s own opening question, asked by the assistant itself — do not duplicate it as static page copy. A portfolio section remains a later phase, only once there is real accepted work to show."}'::jsonb, 'owner-instruction',
  'SQL_2026-08-18e: retired commercial terms swept (owner 2026-08-18). Top-level keys unchanged.',
  true, 'webdesign_uk_build_service lane', c.pinned
FROM cur c, retire;
-- ── strategy ──
WITH cur AS (
  SELECT ss.id, ss.site_id, ss.pinned FROM site_specs ss JOIN sites s ON s.id=ss.site_id
   WHERE s.domain='webdesign.uk' AND ss.aspect='strategy' AND ss.is_current
),
retire AS (UPDATE site_specs ss SET is_current=false, superseded_at=now()
            WHERE ss.id=(SELECT id FROM cur) RETURNING 1)
INSERT INTO site_specs (site_id, aspect, data, source, notes, is_current, created_by, pinned)
SELECT c.site_id, 'strategy', '{"tone": "professional", "site_type": "landing-page", "money_flow": "The customer pays £149 as a single one-off payment in full before any work starts. They do not see the site before paying. There is no approval stage, no revision rounds and no refund: the payment buys one build of a starter site, handed over as it is. Optional recurring revenue comes only from domain rental at £10 a month, or a one-off £200 to buy the domain outright.", "domain_type": "generic_industry", "growth_path": "In the near term the site earns trust through the quality of its own execution and the precision of its commercial terms. The generic domain authority accumulates organic search position for high-value category terms naturally as the site ages and earns links. As builds are delivered, brief specific attributed client feedback replaces the current absence of social proof, added honestly as it exists rather than approximated before it does. A small number of well-chosen case studies showing before-and-after for actual businesses adds the portfolio depth that agency competitors rely on, but only once the work is real. A secondary editorial path targeting plain-English searches that precede commercial intent, such as how much does a website cost in the UK, becomes a sensible acquisition channel in phase two after the conversion page is performing. The contact experience is strengthened in a later phase with a short conversational questionnaire that opens a dialogue rather than qualifying a lead, once the service behind it exists.", "search_intent": {"primary_intent": "commercial", "likely_searches": ["web design uk", "website design uk", "web designer uk", "get a website built uk", "website design for small business uk", "fixed price web design uk", "professional website uk", "hire a web designer uk", "small business website uk", "website design cost uk"], "high_value_terms": ["web design uk", "fixed price web design uk", "website design small business uk", "get a website built uk", "web designer uk"]}, "revenue_models": {"affiliate": {"fit": "poor_fit", "reasoning": "Affiliate links are structurally incompatible with a single-product fixed-price service page. They create conversion friction and signal that the site is not confident in its own offer."}, "saas_tools": {"fit": "poor_fit", "reasoning": "The service is human-delivered. No tool or software component exists or is implied. A SaaS layer would require significant product development and is entirely off-strategy for a fixed-price build service."}, "primary_model": "direct_business", "direct_business": {"fit": "strong_fit", "reasoning": "The site operates as a direct business: one service, one fixed price of £149, one conversion goal. Revenue comes from completed builds paid for up front, before the work starts. The generic domain''s authority lends immediate credibility to the offer without requiring tenure or portfolio signals. This is the correct and already-chosen model."}, "lead_generation": {"fit": "poor_fit", "reasoning": "Selling enquiries to other agencies would waste the domain''s category authority and directly undermine the direct business model already operating. The domain is the credibility signal for the service itself, not a funnel for competitors."}, "secondary_models": [], "sponsored_listings": {"fit": "poor_fit", "reasoning": "A directory or marketplace model would require building a supplier network and editorial infrastructure that does not exist and is not implied. It is off-strategy entirely for a fixed-price build service."}, "display_advertising": {"fit": "poor_fit", "reasoning": "Display advertising on a conversion-focused page creates noise that works against the single goal of turning a sceptical visitor into an enquiry. Pageview monetisation is the wrong shape for this site."}}, "recurring_value": "There is no recurring content draw in phase one; the site is a conversion page not a publishing destination. Return visits occur when a prospect is comparing options across days, and the FAQ and what-you-get pages serve that comparison function directly. Phase two editorial content on website cost and process topics creates a secondary return mechanism for informational searchers.", "trust_threshold": "High, and the trust has to be earned differently now that payment comes first. The buyer distrusts marketing language and is being asked to pay in full before seeing anything, with no refund. What carries them is the smallness and clarity of the commitment: £149 is a low enough figure to risk, the price is genuinely all-in, and every limit is stated plainly and early rather than discovered later. The quality of the site itself, as a live demonstration built by the same system, does the work that testimonials and portfolio depth would do for an established agency.", "content_strategy": "Conversion through radical clarity. Every section answers the next question a sceptical buyer would have before they could ask it. The price is stated early and exactly. The limits are stated just as plainly and just as early: payment first, no sight of the site before paying, no approval stage, no changes included, no refunds. Nothing is softened, because the whole offer depends on the buyer believing the terms are exactly what they say. The process is numbered and honest about where the work sits. The FAQ handles every reasonable objection in plain spoken sentences. No testimonials, no portfolio gallery, no case studies exist yet and the site does not pretend otherwise. The site itself is the demonstration: a well-made, well-written page built by the system it sells. The writing is the opposite of agency copy: short sentences, ordinary words, no enthusiasm performance. Later phases add plain-English editorial content targeting informational searches that precede commercial intent, and examples once there is real work to show.", "value_proposition": "A complete starter website, any sort of site, built in one pass and usually ready the next day, put live on your own domain, for £149 with no VAT and no ongoing fees. You pay first, there is no approval stage and no changes are included, and you keep the files.", "site_type_reasoning": "This is a single-product fixed-price offer with one conversion goal: turn a sceptical SME owner into an enquiry. The research confirms five pages in phase one (index, how-it-works, what-you-get, faq, contact), but these function as a tightly connected conversion flow rather than a conventional multi-page site with independent entry points. The page is the portfolio, the process explanation, the FAQ, and the CTA. The domain''s authority does the SEO work; the page''s clarity does the conversion work. The site itself is the demonstration piece. A brochure classification would overstate the navigational complexity and understate the single-goal discipline required.", "competitive_position": {"defensible_moat": "The domain itself carries generic category authority that no competitor can replicate. The real moat is the cost structure: the site is built by an AI system in one pass rather than by an agency working through it page by page, so a £149 all-in price with next-day turnaround is not something an hours-based competitor can match without changing how they operate. The fixed price with no VAT eliminates the anxiety of hidden costs in a way that agencies offering bespoke quotes structurally cannot. The site is also its own proof: it was built by the system it sells, which is a demonstration a competitor cannot copy by writing better copy.", "gap_opportunity": "No competitor in the crawled set states a fixed all-in price early and plainly without requiring a discovery call first, or offers next-day turnaround at this price. The gap is structural and it is about cost and speed, not about risk reversal: webdesign.uk can afford to be this cheap and this fast because the build is one-shot and automated. A buyer who has been quoted variable prices, surprised by hidden costs, or left with an unfinished site by a previous agency wants a bounded, finished, cheap thing. The complete-build offer, which removes every task from the buyer including the writing, adds a second structural gap that neither agencies nor DIY platforms fill cleanly. The honest limits, stated up front, are part of the offer rather than a caveat on it.", "current_landscape": "The competitive set divides into two groups. Established multi-page agencies such as plugandplaydesign.co.uk, authenticstyle.co.uk, and cbwebsitedesign.co.uk rely on portfolio depth, named team members, founding tenure, and case studies as their primary trust mechanisms. All require the buyer to initiate contact before understanding the financial terms. None resolves the buyer''s financial risk before the first conversation. All use the agency marketing register that has already eroded trust with the SME audience. On the other side, platform products such as Wix and Squarespace compete on DIY self-serve but place the entire burden of building, writing, and launching on the buyer."}, "domain_type_reasoning": "webdesign.uk names the service category exactly. ''Web design'' is what a buyer types when searching for the service, not a brand name. By conventional domain strategy this would be wasted as a single-business brochure: a generic category domain at the .uk level carries inherent authority that no single-business site should squander on a narrow brochure. However, the research data confirms a deliberate and defensible owner decision to deploy it as a direct fixed-price service business. The domain''s generic authority lends immediate category credibility to the offer without requiring portfolio depth or tenure signals. This classification is recorded accurately while the owner''s commercial decision is respected and carried forward.", "recommended_page_types": [{"page_type": "index", "reasoning": "The home page is the primary conversion surface. It states the offer, the price, and the guarantee plainly, then directs the visitor toward the process explanation and contact. Everything on it earns its place by answering the next question a sceptical buyer would ask. No decorative elements, no invented social proof."}, {"page_type": "content", "reasoning": "Four content pages support the conversion flow: how-it-works (the step-by-step process from first email to live site), what-you-get (exact inclusions and exclusions stated with equal clarity), faq (every hard question answered directly with no softening), and contact (email, phone, and a brief prompt on what to include in a first message). Each page handles a specific objection or information need that the index introduces but does not fully resolve."}, {"page_type": "landing", "reasoning": "The index page functions as a conversion-optimised landing page in addition to its navigational role. It should be built with single-goal discipline: one clear headline, one clear CTA, no decorative elements, and every section designed to reduce hesitation rather than to impress. The how-it-works and what-you-get pages carry secondary landing-page discipline because both pages have a clear job: reduce a specific anxiety and move the reader toward contact."}], "satisfaction_condition": "A visitor leaves knowing exactly what they get for £149, what is not included, how long it takes, that they pay before the site is built, that there is no approval stage and no changes or refunds afterwards, what happens to their domain and hosting, and how to get started."}'::jsonb, 'owner-instruction',
  'SQL_2026-08-18e: retired commercial terms swept (owner 2026-08-18). Top-level keys unchanged.',
  true, 'webdesign_uk_build_service lane', c.pinned
FROM cur c, retire;
-- ── submission ──
WITH cur AS (
  SELECT ss.id, ss.site_id, ss.pinned FROM site_specs ss JOIN sites s ON s.id=ss.site_id
   WHERE s.domain='webdesign.uk' AND ss.aspect='submission' AND ss.is_current
),
retire AS (UPDATE site_specs ss SET is_current=false, superseded_at=now()
            WHERE ss.id=(SELECT id FROM cur) RETURNING 1)
