INSERT INTO site_specs (site_id, aspect, data, source, notes, is_current, created_by, pinned)
SELECT c.site_id, 'vertical_landscape', '{"lessons": {"adapt": ["The portfolio mechanism all three rely on establishes quality through accumulated evidence. The same trust job must be done differently without that history. The quality and plainness of the site itself becomes the demonstration. This should be stated explicitly rather than implied: the site the visitor is reading is the work, and they can judge it accordingly. This turns the absence of a portfolio from a weakness into a proof point, but only if the site is genuinely well made and well written.", "The process page that the second exemplar uses to demystify the experience is the right instinct for the SME audience. The adaptation is not to build a separate page for this purpose but to integrate the same reassurance into a tightly written numbered section within a single scrolling page. The benefit of process transparency is achieved without the navigation overhead of a multi-page architecture.", "The educational content approach the third exemplar uses to capture informational search traffic is a long-term acquisition play worth understanding as a future direction. The adaptation for a new site is to ensure the core commercial pages are earning their keep first. Once the conversion page is performing, plain-English guides targeting the searches that precede commercial intent become a sensible second phase, not a first one.", "The regional identity warmth the second exemplar achieves through named location and named individuals is a legitimate trust mechanism. The adaptation for a service without named individuals is to achieve the same human quality through the voice and specificity of the writing rather than through photographs. A buyer who reads a page that sounds like a real person talking plainly is getting the same underlying reassurance."], "adopt": ["Process transparency works as a conversion mechanism independent of portfolio depth. Explaining what will happen, in what order, and what the buyer needs to do at each step directly reduces the anxiety that stops SME owners from enquiring. The underlying cause is that the unfamiliar nature of commissioning a website creates hesitation, and naming each step concretely removes it. A numbered process section earns its place on the page for this reason alone.", "Plain-language answers to the questions buyers actually ask before they enquire (timeline, what is included, who owns the site, what happens if something goes wrong) serve double duty as objection-handling and as a signal of honest dealing. The FAQ is not a nicety; it is the place where a sceptical reader decides whether to trust the studio. Writing it as direct spoken answers rather than policy document bullet points is the difference between it working and not.", "Making the first contact feel easy and low-stakes is a conversion mechanism. A visible phone number, a clear email address, and a brief prompt telling the buyer what to include in their first message all reduce the moment of hesitation that loses enquiries. The contact page is not a formality; it is the last conversion step and deserves the same directness as every other page.", "The contact page framing used by the third exemplar, which tells the buyer what information to put in their first message, reduces abandonment at the final step by removing the uncertainty of not knowing what to say. The underlying principle is that buyers who are ready to act still need a small push to form the message. Giving them the structure removes that final friction."], "avoid": ["Multi-page architecture with separate service pages dilutes the conversion signal for a single fixed-price product. A buyer who needs a complete website built at one price does not benefit from navigating between a web design page, a branding page, and a process page. The multi-page structure serves agencies with multiple services and multiple buyer types; it is the wrong shape for a single offer with a single CTA.", "Tenure and scale signals (founding year, team size, client count, awards) are the trust mechanisms all three competitors lean on most heavily. These are structurally unavailable to a new service and should not be approximated or implied. Attempting to signal scale or longevity without the evidence behind it is the thing that erodes trust with the exact buyer this service is trying to reach, because that buyer has been misled by exactly these signals before.", "Portfolio galleries as the primary credibility proof require a history of delivered work. Reaching for this before the work exists damages trust with the sceptical SME buyer. The solution is not to approximate a portfolio but to make the site itself the proof, and to say so directly.", "Agency marketing language present across all three exemplars (solutions, digital experience, cutting-edge, passionate, bespoke, transform) is the register that has already damaged trust with the target audience. Avoiding it is not a style preference; it is a positioning decision. A buyer who has been burned by an agency that used this language will read its presence as a warning sign.", "Urgency and pressure language in CTA copy, visible to varying degrees across all three, is counterproductive with a buyer who has been oversold to. The pressure in the offer comes from the guarantee mechanism itself, not from the copy urging action. The CTA should name the next step plainly and stop.", "Vague scope language present across all three (ongoing support, revisions as needed, we handle everything) is what creates the disputes and disappointments that make SME buyers sceptical of the category. Stating clearly what is included and what is not, in equally plain terms, is the differentiator. Clarity about exclusions is as important as clarity about inclusions."]}, "patterns": {"tools": "Blog or editorial section used as an organic acquisition channel appears on two of the three explicitly. Portfolio galleries appear on all three as the primary trust and proof mechanism. Multi-page navigation with service-specific pages appears on all three. Contact forms are present but none uses a low-friction plain-text CTA that tells the buyer exactly what to say and removes the moment of hesitation at the final step. None of the three uses a guarantee mechanism as a conversion tool.", "design": "All three use multi-page architectures with distinct landing pages for services and case studies, which creates organic search entry points but also means the conversion message is distributed across multiple pages rather than concentrated. Visual portfolios are the dominant design feature on all three: image-led galleries, case study cards with client names and sector labels, and hero images drawn from client work. None of the three uses a single-page focused layout optimised purely for conversion of a single fixed-price offer. All carry more visual complexity than a pure conversion page requires, and all rely on accumulated visual evidence (client logos, screenshots, photography) that is structurally unavailable to a new service.", "content": "All three exemplars rely on demonstrated output as their primary trust mechanism: portfolio work, case studies, or published editorial. Process transparency appears in two of the three as a way to reduce pre-enquiry anxiety among buyers unfamiliar with commissioning a website. FAQ sections and plain-language explanations of what the buyer will experience are present across all three to varying degrees. None of the three resolves the financial risk question structurally: all three ask the buyer to trust them based on past evidence and then commit to a conversation before understanding the financial terms. The content depth is consistently thorough on portfolio and process, thin on pricing, and silent on what happens if the buyer is unhappy with the result."}, "confidence": 0.71, "exemplars_analyzed": [{"url": "https://www.plugandplaydesign.co.uk/", "positioning": "Established London and Surrey creative agency targeting mid-market and growth-stage businesses across websites, brand, and digital products. Competes on tenure (founded 2006), team size, and breadth of service rather than price or simplicity. The implicit message is: we have been around long enough that choosing us is safe.", "notable_tools": ["Multi-page site architecture with dedicated case study landing pages, each structured around a named client, a sector, a challenge, and a measurable result. This creates multiple organic search entry points beyond the homepage.", "Careers section that simultaneously signals company scale and health to prospective clients browsing the site."], "trust_signals": ["Founding year stated prominently, implying nearly two decades of continuous operation", "Named client case studies with attributed outcomes and sector labels", "Named team members and roles visible on the site", "Physical office location (Guildford, Surrey) stated", "Award references present", "Service breadth implying a full in-house capability rather than a generalist freelancer"], "success_factors": ["Tenure as risk reduction: a founding year stated prominently converts the passage of time into a buyer reassurance. The logic is that an agency still operating after nearly two decades has satisfied enough clients to survive. The mechanism is not the number itself but what it implies about continuity and accountability.", "Named, attributed case studies with measurable outcomes: presenting client work with sector context, lead times, and specific results (search visibility increases, booking uplifts) gives a browser concrete evidence of output before any conversation begins. The buyer can self-select: if they see a client in a similar sector with a similar goal, the conversion barrier drops.", "Breadth of service as upsell architecture: offering web, brand, ecommerce, and UX under one roof means a client who comes for a website can grow into a long-term account. The positioning rewards clients who plan to scale, which also signals to the casual SME buyer that this is a serious operation.", "Geographic specificity: naming London and Surrey simultaneously captures metropolitan commercial credibility and regional proximity warmth. A buyer in either area finds a reason to prefer them over a faceless national provider.", "Careers section as ambient credibility signal: a live hiring page implies a business healthy enough to be growing. Buyers who are quietly assessing whether an agency will still exist in a year read this as a positive indicator even if they never consciously register it."]}, {"url": "https://authenticstyle.co.uk/", "positioning": "Regional UK agency (Poole, Dorset) targeting small businesses with a friendly, process-transparent approach. Differentiates from larger agencies by being approachable and local, and from freelancers by having a defined process and editorial output. The implicit message is: we explain everything and we are people you can talk to.", "notable_tools": ["Dedicated web design process page walking buyers through each stage of engagement before they enquire, reducing uncertainty and pre-qualification friction.", "Blog or resource section producing plain-English content on marketing topics as an organic acquisition channel targeting the same SME audience who would commission a website."], "trust_signals": ["Named individuals with photographs on the about page", "Client portfolio and attributed case studies", "Transparent description of the working process on a dedicated page", "Local business identity with a named town", "Dedicated reviews or testimonials page with attributed client quotes", "Active editorial output implying an ongoing, functioning business"], "success_factors": ["A dedicated process page reduces pre-enquiry anxiety: SME buyers who have never commissioned a website do not know what they are agreeing to. A step-by-step explanation of what will happen, in what order, and what the buyer needs to do converts an unfamiliar purchase into something that feels manageable. The trust gain is not from the content of the steps but from the willingness to make them visible.", "Named individuals with photographs on the about page make the studio feel human and accountable. A buyer who can picture the person they will be working with is less anxious about committing than one dealing with a brand abstraction.", "Publishing accessible editorial content on marketing and SEO topics earns organic search traffic from the same audience that would commission a website. The content does not need to convert directly; it establishes the studio as competent and generous before any sales conversation begins.", "Regional identity creates proximity warmth that national agencies cannot replicate. A Poole business owner who finds a Poole agency has a reason to prefer them that has nothing to do with price or portfolio.", "The educational posture of the content signals that the studio is not trying to mystify the process to protect its fees, which is a genuine fear among SME buyers who have encountered agencies before."]}, {"url": "https://www.cbwebsitedesign.co.uk/", "positioning": "London-facing agency competing primarily on content volume and search visibility. Produces high-cadence editorial on emerging digital topics (AI search, generative SEO, agency comparisons) to capture informational and commercial-intent traffic. The implicit message is: we are current, prolific, and visible, which signals relevance to buyers researching their options.", "notable_tools": ["High-cadence editorial blog targeting both informational and commercial-intent SEO queries, including emerging topics like generative AI search.", "Portfolio gallery with named client projects as a visual proof mechanism.", "Dedicated contact page with a project-starter prompt guiding the buyer on what to include in their first message."], "trust_signals": ["Portfolio with named and visually presented client projects", "Volume of published content implying an active, ongoing business", "Topical authority through consistent editorial output on a specific and current subject area", "Named client brands in the portfolio including recognisable organisations", "Geographic anchoring to London"], "success_factors": ["High-volume content production captures informational search traffic at the top of the buying funnel. A buyer who finds the site through an AI SEO guide is already pre-qualified as someone thinking about digital visibility, which is adjacent to commissioning a website.", "Producing comparison and round-up content targeting competitive search queries (best web design agencies, top UK studios) captures navigational intent at a moment of high commercial readiness. The buyer who is reading a list of agencies is closer to commissioning than one reading a how-to guide.", "A portfolio page with visually presented named client projects gives undecided buyers the visual reassurance they need before contacting. The mechanism is that seeing the quality of output removes the uncertainty about what they will receive.", "Covering emerging topics like AI search signals that the studio is not behind the curve, which matters to buyers who fear commissioning a site that will be outdated quickly.", "A dedicated contact page with a project-framing prompt reduces the friction of the first message by telling the buyer what information to include, which increases the proportion of first messages that are actionable."]}], "differentiation_opportunity": "None of the three exemplars states a fixed all-in price early and plainly without requiring a discovery call first, and none can deliver in a day. All three ask the buyer to trust them based on past evidence, engage with a discovery process, and pay at the end of it. webdesign.uk differentiates on cost and speed rather than on risk reversal: the site is built by an AI system in one pass, so a £149 all-in price with next-day turnaround is not something an hours-based competitor can match without changing how they operate. The differentiation is structural rather than tonal. It is not that the writing sounds friendlier or the design looks cleaner. It is that the cost structure is genuinely different. The trade the buyer is asked to make is explicit and stated up front: payment before the build, no approval stage, no changes and no refunds, in exchange for a price and a turnaround nobody in this set offers. A sceptical buyer who has been quoted variable prices, surprised by additional costs, or left with an unfinished site by a previous agency wants a bounded, finished, cheap thing, and that is exactly what this is."}'::jsonb, 'owner-instruction',
  'SQL_2026-08-18e: retired commercial terms swept (owner 2026-08-18). Top-level keys unchanged.',
  true, 'webdesign_uk_build_service lane', c.pinned
FROM cur c, retire;

DO $$
DECLARE a text; n int; bad text := '';
BEGIN
  -- Seven phrases that must appear NOWHERE in any current webdesign.uk spec,
  -- EXCEPT inside evidence_base.banned_claims, which exist to MATCH them.
  FOR a IN SELECT unnest(ARRAY['1,?200','only pay if you','(14|fourteen)[ -]days?',
                               'full refund','refund-until-acceptance',
                               'rounds? of (revisions?|changes?)','preview link'])
  LOOP
    SELECT count(*) INTO n
      FROM site_specs ss JOIN sites s ON s.id=ss.site_id
     WHERE s.domain='webdesign.uk' AND ss.is_current AND ss.aspect <> 'evidence_base'
       AND ss.data::text ~* a;
    IF n > 0 THEN bad := bad || format('  %s still asserted in %s spec(s)%s', a, n, chr(10)); END IF;
  END LOOP;
  IF bad <> '' THEN RAISE EXCEPTION 'retired terms survive:%s%s', chr(10), bad; END IF;

  -- Every rewritten aspect must have exactly one current row.
  SELECT count(*) INTO n FROM (
    SELECT ss.aspect FROM site_specs ss JOIN sites s ON s.id=ss.site_id
     WHERE s.domain='webdesign.uk' AND ss.is_current
       AND ss.aspect = ANY (ARRAY['briefing','content_direction','design_intent','identity','mission_brief','roadmap_brief','strategy','submission','vertical_landscape'])
     GROUP BY ss.aspect HAVING count(*) <> 1) x;
  IF n <> 0 THEN RAISE EXCEPTION '%s aspect(s) do not have exactly one current row', n; END IF;
END $$;

COMMIT;
